import { Group, Mesh, PlaneGeometry } from 'three';
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, vec4, mix, step, smoothstep, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colors = {
    background: '#0b0b10',
    surface: '#111117',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38'
  };

  // --- 1. STAGE & BACKDROP PLANE ---
  // Large background plane at z=-2.5 to anchor the element and prevent "void" look
  const bgGeom = new PlaneGeometry(8, 7);
  const bgMat = new MeshBasicNodeMaterial();

  // Custom TSL Shader for the background with vertical vignette/gradient
  bgMat.colorNode = (() => {
    const coords = uv();
    const grad = smoothstep(0.0, 0.5, coords.y).mul(smoothstep(1.0, 0.5, coords.y));
    const finalColor = mix(vec3(0.04, 0.04, 0.06), vec3(0.07, 0.07, 0.09), grad);
    return vec4(finalColor, 1.0);
  })();

  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.set(0, 0, -2.5);
  group.add(bgMesh);

  // --- 2. RIBBON BASE PLATE ---
  // Ribbon dimensions: 7.0w x 0.35h
  const baseGeom = new PlaneGeometry(7.0, 0.35);
  const baseMat = new MeshStandardNodeMaterial({
    color: colors.surface,
    roughness: 0.6,
    metalness: 0.2
  });

  const baseMesh = new Mesh(baseGeom, baseMat);
  baseMesh.position.set(0, 0, 0);
  group.add(baseMesh);

  // --- 3. HAIRLINES ---
  // Top and bottom 0.006-unit hairlines in #23232b
  const lineGeom = new PlaneGeometry(7.0, 0.006);
  const lineMat = new MeshBasicNodeMaterial({ color: 0x23232b });

  const topLine = new Mesh(lineGeom, lineMat);
  topLine.position.set(0, 0.35 / 2 - 0.003, 0.005);

  const bottomLine = new Mesh(lineGeom, lineMat);
  bottomLine.position.set(0, -0.35 / 2 + 0.003, 0.005);

  baseMesh.add(topLine);
  baseMesh.add(bottomLine);

  // --- 4. DATA TICKER CONTENT STRIP ---
  // Extract text items or fallbacks
  const rawItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textStrings = rawItems.length > 0 
    ? rawItems.map(item => item.text) 
    : [
        "CAL NA-01 BEAT 28800 VPH",
        "POWER RESERVE 72H",
        "CASE 40.5 MM 904L",
        "REF 5811 IN STOCK",
        "WAITLIST 1204",
        "NEXT FITTING JUL 18"
      ];

  // Instantiating elements in a single horizontal strip container
  const stripContainer = new Group();
  // Slightly raised to catch light, offset Z
  stripContainer.position.set(0, 0, 0.02);
  baseMesh.add(stripContainer);

  const elements = [];
  const spacing = 1.0; // Spacing logic

  // Create nodes for each text block + tick separator
  textStrings.forEach((text) => {
    const textNode = ctx.fontAtlas.createText(text, {
      fontSize: 13,
      color: colors.paper,
      align: 'center'
    });
    elements.push({ type: 'text', node: textNode });

    // Separator tick: 0.02w x 0.14h in #ff2a38 emissive intensity 1.5
    const tickGeom = new PlaneGeometry(0.02, 0.14);
    const tickMat = new MeshStandardNodeMaterial({
      color: colors.accent,
      emissive: colors.accent,
      emissiveIntensity: 1.5,
      roughness: 0.1,
      metalness: 0.9
    });
    const tickMesh = new Mesh(tickGeom, tickMat);
    elements.push({ type: 'tick', node: tickMesh });
  });

  // Layout the single segment
  let currentX = 0;
  elements.forEach((el) => {
    if (el.type === 'text') {
      // Small manual layout spacing adjustments
      currentX += 0.8;
      el.node.position.set(currentX, 0, 0);
      stripContainer.add(el.node);
      currentX += 0.8;
    } else {
      // Tick separator placement
      currentX += 1.0; // Gaps on both sides
      el.node.position.set(currentX, 0, 0.001);
      stripContainer.add(el.node);
      currentX += 1.0;
    }
  });

  const totalSegmentWidth = currentX;

  // Duplicate strip for seamless loop
  const duplicateContainer = stripContainer.clone();
  duplicateContainer.position.set(totalSegmentWidth, 0, 0.02);
  baseMesh.add(duplicateContainer);

  // --- 5. CONSTANT VELOCITY ROTATION / SCROLLING ANIMATION ---
  const scrollParams = { x: 0 };
  const speed = 0.4; // 0.4 scene units/sec leftward
  const loopDuration = totalSegmentWidth / speed;

  const timeline = gsap.to(scrollParams, {
    x: -totalSegmentWidth,
    duration: loopDuration,
    ease: "none",
    repeat: -1,
    onUpdate: () => {
      stripContainer.position.x = scrollParams.x;
      duplicateContainer.position.x = scrollParams.x + totalSegmentWidth;
    }
  });

  // --- 6. EDGE FADING MASK ---
  // Using custom TSL shader node on the base plate to mask extremes
  baseMat.colorNode = (() => {
    const coords = uv();
    // Fade out at borders 0 to 0.09 and 0.91 to 1.0
    const leftFade = smoothstep(0.0, 0.09, coords.x);
    const rightFade = smoothstep(1.0, 0.91, coords.x);
    const edgeMask = leftFade.mul(rightFade);

    // Mix face color towards the dark background color (#0b0b10) near edges
    const surfaceColor = vec3(0.066, 0.066, 0.09); // #111117 equivalent
    const bgColor = vec3(0.043, 0.043, 0.062); // #0b0b10 equivalent

    return vec4(mix(bgColor, surfaceColor, edgeMask), 1.0);
  })();

  // Run the cinematic primitives
  let primitiveInstance = null;
  if (config.cinematicPrimitives) {
    const prim = config.cinematicPrimitives.find(p => p.name === 'fly-through');
    if (prim && ctx.primitives['fly-through']) {
      primitiveInstance = ctx.primitives['fly-through'](group, prim.params);
    }
  }

  // Handle Event / Cleanups
  group.userData = {
    handlers: {},
    cleanup: () => {
      timeline.kill();
      if (primitiveInstance && primitiveInstance.cleanup) {
        primitiveInstance.cleanup();
      }
      baseGeom.dispose();
      baseMat.dispose();
      bgGeom.dispose();
      bgMat.dispose();
      lineGeom.dispose();
      lineMat.dispose();
    }
  };

  return group;
}
